  (function() {
    const webhookData = $('WAHA Trigger').first().json;
    const payload = webhookData.payload || {};
    const eventName = webhookData.event || "";

    // 1. Blokir status ack (centang dua/read receipt)
    if (eventName.includes('ack')) return "TOLAK"; 

    // 2. Blokir pesan dari diri sendiri
    const fromMe = payload.fromMe || (payload.key && payload.key.fromMe) || false;
    if (fromMe === true) return "TOLAK"; 

    // 3. FILTER GRUP ANTI-BUDEK
    const from = payload.from || "";
    if (from.includes('@g.us')) {

      // Ambil otomatis ID Bot (Nomor HP) dan LID Bot dari sistem
      const botIdRaw = (webhookData.me && webhookData.me.id) ? webhookData.me.id.split('@')[0] : "";
      const botLidRaw = (webhookData.me && webhookData.me.lid) ? webhookData.me.lid.split('@')[0] : "";

      const text = payload.body || "";

      // Satpam ngecek teks: Apakah ada tag pake Nomor HP ATAU pake LID?
      const isMentionedText = (botIdRaw && text.includes('@' + botIdRaw)) || (botLidRaw && text.includes('@' + botLidRaw));

      // Satpam ngecek sistem (mentionedJid): Kita ubah seluruh payload jadi string biar gampang dicari
      const payloadString = JSON.stringify(payload);
      const isTaggedOfficial = (botIdRaw && payloadString.includes(botIdRaw)) || (botLidRaw && payloadString.includes(botLidRaw));

      // Kalau dua identitas bot lu (HP & LID) nggak dipanggil sama sekali, TENDANG!
      if (!isMentionedText && !isTaggedOfficial) {
        return "TOLAK";
      }
    }

    // Kalau di-tag (baik pake LID atau nomor), MASUK KE TRUE!
    return "LULUS"; 
  })()
}}

