// =====================================================================
// 1. TARIK MEMORI & CHAT ID (SEDOT LANGSUNG DARI SUMBER)
// =====================================================================
let history_lama = [];
let chatId = "";
let pesanBaru = "";

// --- Tarik Memori Langsung dari Terminal (Bypass Sortir) ---
try {
  // Ambil teks JSON mentah hasil dari command 'cat'
  let teksMentah = $('memory masuk').first().json.stdout || "[]";
  let rawHistory = JSON.parse(teksMentah.trim());

  if (Array.isArray(rawHistory)) {
      // Bersihkan system prompt dari masa lalu
      history_lama = rawHistory.filter(msg => msg.role !== "system");
  } else {
      history_lama = [];
  }
} catch (e) {
  // Kalau file di CasaOS kosong/error, mulai dari nol
  history_lama = [];
}

// --- Tarik Chat ID Mentah (@lid) ---
try {
  let wahaNode = $('WAHA Trigger').first().json;
  if (wahaNode.payload && wahaNode.payload.from) {
      chatId = wahaNode.payload.from; 
      pesanBaru = wahaNode.payload.body || ""; 
  } else if (wahaNode.body && wahaNode.body.from) {
      chatId = wahaNode.body.from;
      pesanBaru = wahaNode.body.body || ""; 
  } else {
      chatId = "Data_From_Kosong"; 
  }
} catch (e) {
  chatId = "ERROR_NAMA_NODE_TRIGGER_SALAH";
}
// =====================================================================
// 2. AMBIL HASIL PENCARIAN GOOGLE (Node: search enggine)
// =====================================================================
let contextInfo = "";
let searchResults = null;

try {
  let serperNode = $('search enggine').first(); 
  if (serperNode && serperNode.json && serperNode.json.organic) {
    searchResults = serperNode.json.organic;
  }
} catch (error) {
  searchResults = null; 
}

if (searchResults && searchResults.length > 0) {
  contextInfo = searchResults.slice(0, 5).map(res => {
    return `Title: ${res.title}\nContent: ${res.snippet}\nLink: ${res.link}`;
  }).join("\n\n=================\n\n");
}

// =====================================================================
// 3. GABUNGKAN PESAN BARU DENGAN DATA GOOGLE
// =====================================================================
let finalUserMessage = pesanBaru;

if (contextInfo !== "") {
    finalUserMessage += `\n\n[SYSTEM DATA: REAL-TIME INTERNET SEARCH RESULTS]\n${contextInfo}\n\nInstruction: Provide a comprehensive answer based on the data above. If a location is mentioned, include estimated pricing and a Google Maps link.`;
}

// =====================================================================
// 4. SYSTEM PROMPT (Persona Aria) - TIDAK DIRUBAH SAMA SEKALI
// =====================================================================
let systemPrompt = `You are Aria, an authentic, supportive, and witty AI assistant. 

CORE PERSONALITY:
- Tone: Adaptive, cool, and peer-like. 
- Wit: Use subtle humor regarding tech or gold trading.
- Empathy: Validate Fauzan's feelings, but correct significant misinformation gently.

STRICT OPERATIONAL RULES:
1. OUTPUT LANGUAGE: Always respond in INDONESIAN (Bahasa Indonesia) using a relaxed/casual style (Gaya bahasa santai).
2. MEMORY: Utilize the provided conversation history. NEVER claim you don't remember previous messages.
3. PLACE DETAILS: If asked about a location, provide:
   - Estimated price range (e.g., "Mulai dari Rp 25.000").
   - A direct Google Maps link.
4. SOCIAL MEDIA: Provide URLs as PLAIN TEXT only. Do NOT use markdown links [text](url). 
5. FORMATTING: Use bullet points for readability.`;

// =====================================================================
// 5. RAKIT ARRAY MESSAGES (URUTAN WAJIB: SYSTEM -> HISTORY LAMA -> PESAN BARU)
// =====================================================================
let finalMessages = [];

// A. Taruh System Prompt di posisi paling atas (otak utama)
finalMessages.push({ role: "system", content: systemPrompt });

// B. Masukkan History Lama (Dibatasi 10 terakhir agar STB/API tidak jebol)
let limitedHistory = history_lama.slice(-10);
finalMessages = finalMessages.concat(limitedHistory);

// C. Masukkan Pesan User Hari Ini di posisi paling bawah
if (finalUserMessage.trim() !== "") {
    finalMessages.push({ role: "user", content: finalUserMessage });
} else if (limitedHistory.length === 0) {
    // Fallback darurat jika pesan kosong
    finalMessages.push({ role: "user", content: "Halo" }); 
}

// =====================================================================
// 6. KIRIM KE NODE SELANJUTNYA (Format Standar n8n)
// =====================================================================
return {
  json: {
    chat_id: chatId,
    messages: finalMessages
  }
};

// =====================================================================
// NODE: PROMPT VISION UNTUK HUGGING FACE (LLaVA)
// =====================================================================
let chatId = "Data_From_Kosong";
let pesanBaru = "";
let base64Gambar = null;
let mimeTypeGambar = null;

// 1. Tarik Data WAHA
try {
  let wahaNode = $('WAHA Trigger').first().json;
  if (wahaNode.payload && wahaNode.payload.from) {
      chatId = wahaNode.payload.from;
      pesanBaru = wahaNode.payload.body || ""; 
  }
} catch (e) {}

// 2. Tarik Gambar
try {
  let nodeGambar = $('image').first(); 
  if (nodeGambar && nodeGambar.binary && nodeGambar.binary.data) {
      base64Gambar = nodeGambar.binary.data.data;
      mimeTypeGambar = nodeGambar.binary.data.mimeType;
  }
} catch (e) {}

// 3. Setup Pertanyaan & Format Gambar
let pertanyaan = pesanBaru.trim() !== "" ? pesanBaru : "Tolong analisis dan jelaskan gambar ini secara detail menggunakan bahasa Indonesia.";

let gambarDataURI = "";
if (base64Gambar) {
    // Kita kirim Base64 mentahnya aja biar CloudFront nggak ngamuk
    gambarDataURI = base64Gambar; 
}

// 4. Kirim ke Node HTTP Request HF
return {
  chat_id: chatId,
  pertanyaan: pertanyaan,
  gambar_base64: gambarDataURI
};

// 1. Ambil teks asli dari WAHA Trigger
let originalText = $('HTTP Request1').first().json.responseData.translatedText || "";

// 2. Bersihkan trigger basa-basi (kayak: "tolong buatkan gambar...")
let cleanPrompt = originalText.replace(/.*(buatkan|bikin|generate|tolong|coba).*(gambar|desain|ui|logo|lukisan|ilustrasi)\s*/i, '').trim();

// 3. Deteksi Jenis Permintaan
let isUI = originalText.toLowerCase().match(/(ui|ux|login page|dashboard|web|app|interface|website|desain|aplikasi)/i);
let isIllustration = originalText.toLowerCase().match(/(ilustrasi|illustration|kartun|anime|vektor|vector)/i);

let aestheticBumbu = "";
let styleUsed = "";

if (isUI) {
  // Bumbu khusus UI/UX: Kita bikin BANYAK PILIHAN biar nggak bosen!
  const uiStyles = [
    ", Glassmorphism style, frosted glass effect, modern aesthetic, soft pastel gradients, clean typography, high fidelity UI",
    ", Dark mode UI, neon accents, cyberpunk aesthetic, modern dashboard, sleek dark background, glowing data visualization",
    ", Neumorphism style, soft shadows, extruded UI elements, minimalist white and grey color palette, very clean and sharp",
    ", Apple iOS flat design style, minimalist, plenty of whitespace, rounded corners, professional enterprise application, clear fonts",
    ", Dribbble trending UI, vibrant gradient colors, 3D colorful icons, engaging layout, playful but professional web design",
    ", Clean corporate style, professional layout, blue and white color scheme, structured grid, highly readable UI"
  ];

  // Pilih gaya secara acak dari array di atas
  let randomUI = uiStyles[Math.floor(Math.random() * uiStyles.length)];

  // Tambahin instruksi wajib biar teksnya kebaca
  aestheticBumbu = randomUI + ", readable text placeholders, precise layout, sharp details";
  styleUsed = "UI/UX (" + randomUI.split(',')[1].trim() + ")";

} else if (isIllustration) {
  // Bumbu khusus Ilustrasi
  aestheticBumbu = ", professional digital illustration, vibrant colors, clean lines, detailed background, clear shapes";
  styleUsed = "Illustration";

} else {
  // Bumbu Fotorealistik (Sesuai request lu: Biasa aja, ga usah 8k, yang penting jelas & tajam)
  aestheticBumbu = ", realistic, clear details, well-lit, sharp focus, good quality photography";
  styleUsed = "Realistic (Standard)";
}

let finalPrompt = cleanPrompt + aestheticBumbu;

return {
  prompt: finalPrompt,
  original_prompt: cleanPrompt,
  style_used: styleUsed
};

