// 1. Tembak langsung ke node "WAHA Trigger" buat ngambil data utuh
const webhookData = $('WAHA Trigger').first().json;
const payload = webhookData.payload || {};

// 2. Misi Pencarian Nomor Asli (Harta Karun di remoteJidAlt)
let rawId = "";

// Kita intip ke dalem payload._data.key buat nyari remoteJidAlt
if (payload._data && payload._data.key && payload._data.key.remoteJidAlt) {
    // Kalau harta karunnya (nomor asli) ketemu, pake ini!
    rawId = payload._data.key.remoteJidAlt; 
} else {
    // Kalau nggak ada (misal chat pribadi biasa), balik pake cara normal
    rawId = payload.from || webhookData.lid || "";
}

// 3. Ekstrak angkanya saja (Menebas @s.whatsapp.net, @c.us, atau @lid)
const pureNumber = rawId.split('@')[0];

// 4. Outputkan datanya dengan rapi
return {
  json: {
    fileName: `${pureNumber}.txt`,
    nomorAsli: pureNumber
  }
};

// 1. Cek apakah node "Read File" berhasil dapet isi teksnya
let nomorDariFile = "";
if ($input.all().length > 0 && $input.first().json.data) {
    nomorDariFile = $input.first().json.data;
}

